"use strict";(self.webpackChunksketch_blog=self.webpackChunksketch_blog||[]).push([[4485],{12(a,e,p){p.r(e),p.d(e,{_pageData:()=>n,default:()=>t});var h=p(641);const n=JSON.parse('{"path":"/notes/%E4%B9%A6%E5%BD%B1%E9%9F%B3%E6%B8%B8/%E4%B9%A6%E7%B1%8D/%E4%B8%80%E5%9C%B0%E9%B8%A1%E6%AF%9B.html","title":"一地鸡毛","lang":"zh-CN","frontmatter":{"title":"一地鸡毛","date":"2023-04-17T00:00:00.000Z","tags":["读书"]},"git":{},"filePathRelative":"notes/书影音游/书籍/一地鸡毛.md"}'),s={name:"一地鸡毛.md"},t=(0,p(6262).A)(s,[["render",function(a,e,p,n,s,t){return(0,h.uX)(),(0,h.CE)("div",null,[...e[0]||(e[0]=[(0,h.Fv)('<h1 id="一地鸡毛" tabindex="-1"><a class="header-anchor" href="#一地鸡毛"><span>一地鸡毛</span></a></h1><h2 id="一地鸡毛-1" tabindex="-1"><a class="header-anchor" href="#一地鸡毛-1"><span>一地鸡毛</span></a></h2><p>主角两人在鸡毛蒜皮的争吵中过日子，慢慢变好的故事。</p><p>经历了豆腐（馊了）、水表（偷水）、换工作（求人办事）、通车（沾领导光？）、没帮助老师、幼儿园（给其他家当伴读）、收礼办事这些事情，仍然对生活抱有希望。</p><p>每个人都在一地鸡毛中过着自己的日子。</p><p>情节和我看到书名预想的不一致，我还以为是一地鸡毛之后会发生什么悲剧。</p><h2 id="塔铺" tabindex="-1"><a class="header-anchor" href="#塔铺"><span>塔铺</span></a></h2><p>刚恢复高考时期，描写了主角及其他几人在塔铺上学的故事。</p><h3 id="主线" tabindex="-1"><a class="header-anchor" href="#主线"><span>主线：</span></a></h3><p>主角和女主相爱，因女主家贫，亲人生病，无奈出嫁。男主高考完之后才发现，爱而不得的故事。</p><h3 id="支线" tabindex="-1"><a class="header-anchor" href="#支线"><span>支线：</span></a></h3><p>其他几人各怀心思来塔铺上学的始末</p><p>追女生的，失败，末期想学习，为时已晚。</p><p>逃避农活的，自身不够聪明，在农忙时想通，不再高考，回家种地。</p><p>想摆脱贫困来塔铺学习的，高考时过度紧张（还是其他原因？吃中毒了？忘了），晕倒在考场，功亏一篑（好像不晕倒考上的希望也渺茫）</p>',15)])])}]])}}]);